const TRAINING_SPEC_FIELDS=[["dataset_id","Dataset"],["tag","Tag"],["control_dt_minutes","Decision minutes"],["steps","Decision budget"],["eval_every","Evaluation target (decisions)"],["validation_periods","Validation periods"],["test_periods","Test periods"],["hidden_dim","Hidden width"],["gamma","Gamma (per decision)"],["learning_rate","Learning rate"],["batch_size","Batch size"],["replay_capacity","Replay capacity"],["learning_starts","Learning starts (replay)"],["target_sync_interval","Target sync (gradient updates)"],["epsilon_start","Epsilon start"],["epsilon_end","Epsilon end"],["epsilon_decay_steps","Epsilon decay (decisions)"],["reward_divisor_vnd","Reward divisor (VND)"],["gradient_clip_norm","Gradient clip norm"],["seed","Seed"],["device","Device"],["resume","Resume"]];
